<?php
$pageTitle='Actividad';$basePath='../';$adminScripts=true;$adminActive='actividad';require_once __DIR__.'/../auth.php';requireAdmin('../login.php','../usuario/index.php');require_once __DIR__.'/../firebase-data.php';
$usersRaw=firebaseRead(fn(FirebaseReadService $f)=>$f->rtdb('usuarios'));$users=is_array($usersRaw)?$usersRaw:[];
$orders=array_values(array_filter(firebaseRead(fn(FirebaseReadService $f)=>$f->collection('pedidos')), 'is_array'));$reservations=array_values(array_filter(firebaseRead(fn(FirebaseReadService $f)=>$f->collection('reservas')), 'is_array'));$messages=array_values(array_filter(firebaseRead(fn(FirebaseReadService $f)=>$f->collection('mensajes')), 'is_array'));$audit=normalizeAuditRecords(firebaseRead(fn(FirebaseReadService $f)=>$f->collection('auditoria_admin')));$events=[];
foreach($orders as $o){$type=(strtolower((string)($o['tipoUsuario']??''))==='fisico'||strtolower((string)($o['origenPedido']??''))==='pulsador')?'venta_fisica':'pedido';$events[]=['date'=>$o['fechaCreacion']??null,'type'=>$type,'actor'=>$o['nombreUsuario']??$o['usuarioId']??'Sin actor','description'=>orderSummary($o).' · '.money($o['total']??null),'origin'=>orderOrigin($o)];}
foreach($reservations as $r)$events[]=['date'=>$r['fechaCreacion']??$r['fechaSolicitada']??null,'type'=>'reserva','actor'=>$r['nombreCliente']??$r['usuarioId']??'Sin actor','description'=>$r['detalle']??'Reserva CHICHEJ','origin'=>'Firestore'];foreach($messages as $m)$events[]=['date'=>$m['fechaCreacion']??null,'type'=>($m['tipo']??'')==='promocion'?'promocion':'informativo','actor'=>$m['creadoPorNombre']??'Administración','description'=>$m['titulo']??'Publicación CHICHEJ','origin'=>'Firestore'];foreach($users as $uid=>$u)if(is_array($u))$events[]=['date'=>$u['fechaRegistro']??null,'type'=>'registro_usuario','actor'=>$u['nombre']??$uid,'description'=>'Registro de usuario','origin'=>'RTDB'];
$sortNewest=fn($a,$b)=>(firebaseDate($b['date']??$b['fecha']??null)?->getTimestamp()??0)<=>(firebaseDate($a['date']??$a['fecha']??null)?->getTimestamp()??0);usort($events,$sortNewest);usort($audit,$sortNewest);$now=new DateTimeImmutable('now',new DateTimeZone('America/La_Paz'));
$periodTags=static function(mixed $value)use($now):string{$date=firebaseDate($value)?->setTimezone(new DateTimeZone('America/La_Paz'));$tags=['all'];if($date){if($date->format('Y-m-d')===$now->format('Y-m-d'))$tags[]='today';if($date>=$now->modify('-6 days')->setTime(0,0))$tags[]='7days';if($date->format('Y-m')===$now->format('Y-m'))$tags[]='month';if($date->format('Y')===$now->format('Y'))$tags[]='year';}return implode('|',$tags);};$admins=[];$actions=[];foreach($audit as $entry){if($entry['adminNombre'])$admins[$entry['adminNombre']]=true;if($entry['accion'])$actions[$entry['accion']]=true;}ksort($admins);ksort($actions);
require __DIR__.'/../header.php';require __DIR__.'/../navbar.php';require __DIR__.'/../admin-nav.php';
