<section id="auditoria" class="admin-data activity-section" data-filter-scope><div class="analytics-head"><div><small>Firestore · auditoria_admin</small><h2>Auditoría administrativa</h2></div><span><?=count($audit)?> registros reales</span></div><div class="admin-filterbar"><label class="admin-search">Buscar<input type="search" data-filter-search placeholder="Administrador, acción, producto o usuario…"></label><label>Administrador<select data-filter-key="admin"><option value="">Todos</option><?php foreach(array_keys($admins) as $admin):?><option value="<?=h($admin)?>"><?=h($admin)?></option><?php endforeach;?></select></label><label>Acción<select data-filter-key="action"><option value="">Todas</option><?php foreach(array_keys($actions) as $action):?><option value="<?=h($action)?>"><?=h(auditActionLabel($action))?></option><?php endforeach;?></select></label><label>Período<select data-filter-key="period"><option value="all">Todos</option><option value="today">Hoy</option><option value="7days">Últimos 7 días</option><option value="month">Este mes</option><option value="year">Este año</option></select></label><span data-filter-count><?=count($audit)?> registros</span></div><?php if(!$audit):?><div class="audit-empty"><span>◎</span><h2>Sin registros disponibles</h2><p><?=firebaseReadFailed()?'No fue posible consultar auditoria_admin en este momento.':'La colección no devolvió documentos.'?></p></div><?php else:?><div class="audit-list admin-scroll-list" tabindex="0"><?php foreach($audit as $entry):$subject=$entry['productoNombre']??$entry['productoId']??$entry['usuarioNombre']??$entry['usuarioUid']??$entry['entidadId']??'Sin entidad';$module=$entry['modulo']??($entry['productoId']||$entry['productoNombre']?'Producto':($entry['usuarioUid']||$entry['usuarioNombre']?'Usuario':'Sin módulo'));?><article class="audit-row" data-filter-row data-search="<?=h(implode(' ',array_filter([$entry['adminNombre'],$entry['adminRol'],$entry['accion'],$module,$subject,$entry['descripcion'],auditValueText($entry['valorAnterior']),auditValueText($entry['valorNuevo'])])))?>" data-admin="<?=h($entry['adminNombre']??'')?>" data-action="<?=h($entry['accion']??'')?>" data-period="<?=h($periodTags($entry['fecha']))?>"><div class="audit-row__head"><time><?=h(displayDate($entry['fecha']))?></time><span><?=h(auditActionLabel($entry['accion']))?></span></div><div><small>Administrador</small><strong><?=h($entry['adminNombre']??$entry['adminUid']??'Sin datos')?></strong><p><?=h($entry['adminRol']??'Rol sin datos')?></p></div><div><small><?=h($module)?></small><strong><?=h($subject)?></strong><p><?=h($entry['descripcion']??'Sin descripción')?></p></div><dl><div><dt>Valor anterior</dt><dd><?=h(auditValueText($entry['valorAnterior']))?></dd></div><div><dt>Valor nuevo</dt><dd><?=h(auditValueText($entry['valorNuevo']))?></dd></div></dl></article><?php endforeach;?></div><p data-filter-empty hidden>No hay registros de auditoría para los filtros seleccionados.</p><?php endif;?></section></div></section></main>
